import {esc,num} from './marine-charts.js?v=8.8';
export function terrainSource(target) {
  const originalUSGS=String(target.id).startsWith('SC26-');
  return {producer:target.producer||(originalUSGS?'USGS':'Survey provider'),datum:target.vertical_datum||(originalUSGS?'MLLW':'not recorded'),
    grid:target.native_resolution_range_m?`${target.native_resolution_range_m.join('–')} m native survey cells; ${target.analysis_cell_m} m analysis grid`:originalUSGS?'10 m analysis grid (about 33 ft)':'Grid resolution not recorded'};
}
export function terrainMetricsHTML(target) {
  const m=target.metrics||{},rating=target.rating;
  if(rating){
    const labels={relief:'Local relief',complexity:'Unevenness after removing slope',hard_area:'Supported hard substrate area'};
    return `<h3>Why this terrain ranks here</h3><p>${esc(rating.score_type)} · ${target.habitat_score}/100. Scores made with different regional methods are not directly comparable.</p><dl class="terrain-components">${Object.entries(rating.score_components||{}).map(([key,value])=>`<dt>${esc(labels[key]||key)}</dt><dd>${num(value)} points</dd>`).join('')}</dl><p>Central 90% depth range: ${num(rating.relief_90_percent_m*3.28084)} ft. Unevenness: ${num(rating.plane_residual_rms_m*3.28084)} ft RMS. These are neighborhood measurements, not individual rock dimensions.</p><details><summary>Rating method & depth screen</summary><p>${esc(rating.score_method)}</p><p>Deepest included cell with reported product uncertainty and ${num(target.qualification?.planning_margin_m)} m planning allowance: ${num(target.qualification?.max_depth_including_uncertainty_and_margin_ft)} ft. Full outline screened against protected areas with ${num(target.qualification?.closure_clearance_m,0)} m clearance.</p></details><p class="small">A repeatable habitat search priority, not a validated species or catch score. Confirm the bottom and fish with your sounder.</p>`;
  }
  const rows=[['Local relief',m.relief_210m_m*3.28084,'ft',Math.min(m.relief_210m_m/15,1),35,'Local height change; full credit at 15 m. Not boulder height.'],['Rough / bedrock cover',m.rugose_or_bedrock_fraction_210m===null?null:m.rugose_or_bedrock_fraction_210m*100,'%',m.rugose_or_bedrock_fraction_210m,30,'Fraction of mapped rough seabed or bedrock in the analysis neighborhood.'],['Seabed unevenness',m.plane_residual_rms_250m_m*3.28084,'ft RMS',Math.min(m.plane_residual_rms_250m_m/3,1),20,'Variation after removing overall slope; full credit at 3 m RMS.'],['Nearby rough habitat',m.rough_habitat_within_250m_ha*2.47105,'acres',Math.min(m.rough_habitat_within_250m_ha/10,1),15,'Within 250 m; full credit at 10 ha. Area alone cannot earn an A.']];
  return '<h3>Why this terrain ranks here</h3>'+rows.map(([label,value,unit,fraction,weight,note])=>`<div class="metric-row"><div><span>${label}</span><strong>${num(value)} ${unit}</strong></div>${Number.isFinite(fraction)?`<div class="meter"><span style="width:${Math.round(fraction*100)}%"></span></div><span class="score-points">${num(fraction*weight)} of ${weight} points</span>`:'<span>Not measured</span>'}<p class="small metric-explanation">${note}</p></div>`).join('')+'<p class="small">Weighted contributions sum to the rounded terrain score. This formula has not been validated against catches. <a href="sources.html#grades">Grading method.</a></p>';
}
